func TestReproUnbufferedDeadlock(t *testing.T) {
	ack := make(chan struct{})
	done := make(chan struct{})
	go func() { ack <- struct{}{}; close(done) }()
	select {
	case <-done: t.Fatal("expected blocking ack")
	case <-time.After(200 * time.Millisecond):
		t.Log("DEADLOCK REPRODUCED: unbuffered ack blocked")
	}
}
